#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

if [[ "$ENV_FILE" == ".env" ]]; then
  if [[ -n "${LOCALAPPDATA:-}" ]] && command -v cygpath >/dev/null 2>&1; then
    SECRET_DIR="$(cygpath -u "$LOCALAPPDATA")/dynamic-leverage-2x/secrets"
  elif [[ -n "${LOCALAPPDATA:-}" ]] && command -v wslpath >/dev/null 2>&1; then
    SECRET_DIR="$(wslpath "$LOCALAPPDATA")/dynamic-leverage-2x/secrets"
  else
    SECRET_DIR="$HOME/.local/share/dynamic-leverage-2x/secrets"
  fi
  ENV_FILE="$SECRET_DIR/runtime.env"
else
  SECRET_DIR="$(dirname "$ENV_FILE")"
fi
mkdir -p "$SECRET_DIR"
chmod 700 "$SECRET_DIR" 2>/dev/null || true

banner "Dynamic Leverage Control secrets setup"

stage "Shioaji API credentials"
say "Store the API key and secret you already created. Input is hidden and never echoed."
open_url "https://sinotrade.github.io/tutor/prepare/token/"
ask_secret SJ_API_KEY "Paste SJ_API_KEY:"
ask_secret SJ_SECRET_KEY "Paste SJ_SECRET_KEY:"
write_env SJ_API_KEY "$SJ_API_KEY"
write_env SJ_SECRET_KEY "$SJ_SECRET_KEY"

stage "Bind the strategy stock account"
say "The API will log in read-only and list your stock accounts with masked IDs."
say "Choose the number of the account this platform is allowed to observe."
if ! command -v docker >/dev/null 2>&1; then
  warn "Docker is required for account discovery. Start Docker Desktop and re-run this wizard."
  exit 1
fi
account_error_file=$(mktemp)
account_candidates_raw=""
if ! account_candidates_raw=$(DVL_SECRET_FILE="$ENV_FILE" docker compose run --rm --no-deps api dvl shioaji-accounts 2>"$account_error_file"); then
  if grep -qi "Sign data is timeout" "$account_error_file"; then
    warn "Shioaji login timed out. Check Windows/Docker clock sync and retry."
  else
    warn "Could not discover Shioaji accounts. Build/start the stack, then re-run this wizard."
  fi
  rm -f "$account_error_file"
  exit 1
fi
rm -f "$account_error_file"
account_candidates=$(printf '%s\n' "$account_candidates_raw" | grep -E '^[0-9]+[[:space:]]+[^[:space:]]+[[:space:]]+(signed|needs-signing)$' || true)
if [[ -z "$account_candidates" ]]; then
  warn "No signed stock account was returned by Shioaji. Complete API signing/test first."
  exit 1
fi
printf '  Available stock accounts:\n%s\n' "$account_candidates"
ask SHIOAJI_ACCOUNT_INDEX "Enter the account list number to bind (for example 0):"
case "$SHIOAJI_ACCOUNT_INDEX" in
  ''|*[!0-9]*)
    warn "Account selection must be a number."
    exit 1
    ;;
esac
account_binding_raw=$(DVL_SECRET_FILE="$ENV_FILE" docker compose run --rm --no-deps api dvl shioaji-accounts --index "$SHIOAJI_ACCOUNT_INDEX" 2>/dev/null) || {
  warn "That account selection was not valid. Re-run the wizard."
  exit 1
}
SHIOAJI_ACCOUNT_ID=$(printf '%s\n' "$account_binding_raw" | grep -E '^[^-[:space:]]+-[^-[:space:]]+$' | tail -n 1)
account_broker="${SHIOAJI_ACCOUNT_ID%%-*}"
account_number="${SHIOAJI_ACCOUNT_ID#*-}"
case "$account_number" in
  *-*)
    warn "Shioaji returned an invalid account binding."
    exit 1
    ;;
esac
if [ -z "$account_broker" ] || [ -z "$account_number" ] || [ "$account_broker" = "$SHIOAJI_ACCOUNT_ID" ]; then
  warn "Shioaji returned an invalid account binding."
  exit 1
fi
write_env SHIOAJI_ACCOUNT_ID "$SHIOAJI_ACCOUNT_ID"

stage "Shioaji CA certificate (optional for now)"
say "Production orders remain disabled. Leave these blank until your CA is ready."
open_url "https://sinotrade.github.io/tutor/prepare/ca/"
ask SHIOAJI_CA_PATH "Absolute CA certificate path, or Enter to skip:"
ask_secret SHIOAJI_CA_PASSWORD "CA password, or Enter to skip:"
write_env SHIOAJI_CA_PATH "$SHIOAJI_CA_PATH"
write_env SHIOAJI_CA_PASSWORD "$SHIOAJI_CA_PASSWORD"

stage "Telegram alerts (optional)"
say "Create a private bot with BotFather, send it one message, then capture its token and chat ID."
open_url "https://core.telegram.org/bots/features#botfather"
ask_secret TELEGRAM_BOT_TOKEN "Bot token, or Enter to skip:"
ask TELEGRAM_CHAT_ID "Private chat ID, or Enter to skip:"
write_env TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
write_env TELEGRAM_CHAT_ID "$TELEGRAM_CHAT_ID"

stage "FinMind supplemental token (optional)"
say "FinMind is only for backfill and cross-checking; it can never authorize a live trade."
open_url "https://finmind.github.io/en/quickstart/"
ask_secret FINMIND_TOKEN "FinMind token, or Enter to skip:"
write_env FINMIND_TOKEN "$FINMIND_TOKEN"

stage "Restrict and verify the secret file"
chmod 600 "$ENV_FILE" 2>/dev/null || true
say "The file is stored outside the repository and is not printed."
say "Secret file: $ENV_FILE"
note "On Windows, keep this file under your own LocalAppData account and do not share it."
confirm "Confirm that production order submission must remain disabled?" || {
  warn "Setup stopped because the safety boundary was not confirmed."
  exit 1
}

finish
